/* Call-frame registry: each per-site call frame self-registers (via a C
 * constructor) a stable name <-> DKFrame mapping, so a call frame marshals as
 * its name rather than a code address -- the same name-keyed scheme the
 * interpreter's serial.c uses, here with the emitted C function name. */
/* env_kind: 0 = int (inline int64), 1 = cstr (length-prefixed bytes),
 * 2 = serializable (marshaled via the env type's Serializable instance). For a
 * serializable env, ser/deser point at __inst_Serializable_{serialize,
 * deserialize}_<T>: ser(env) -> a `bytes` {int64 len; data} buffer; deser(bytes)
 * -> the env value. */
typedef struct SkReg {
    const char *name; DKFrame fn; int env_kind;
    void *(*ser)(int64_t); int64_t (*deser)(void *);
    struct SkReg *next;
} SkReg;
extern SkReg *__sk_registry;
